-- Tensor key : enc1.block.0.weight (kernel 0 only), folded with
--              enc1.block.1 (BatchNorm2d, eval-mode running stats)
--
-- ---- BatchNorm folding ----------------------------------------------------
-- scale_bn[0] = 1.515678
-- b_folded[0] = -0.014275
-- (eps = 1e-05, torch.nn.BatchNorm2d default)
--
-- ---- Folded weight quantization ------------------------------------------
-- scale_w_folded[0] = 0.00206228
